+/// Python `float()` of a `le` label (`floatToGoString` output, so `+Inf` too).
+fn parse_python_float(s: &str) -> f64 {
+    match s {
+        "+Inf" | "inf" | "Inf" => f64::INFINITY,
+        "-Inf" | "-inf" => f64::NEG_INFINITY,
+        _ => s.parse().unwrap_or(f64::NAN),
+    }
+}
